local zones = {
	[947] = {
		name = "Azeroth",
		short = "Il y a dix mille ans, les Bien-nés de Kalimdor, enivrés par la puissance du Puits d'éternité, répondirent à l'appel du titan déchu Sargeras et ouvrirent un passage à la Légion ardente.",
		full = "Il y a dix mille ans, les Bien-nés de Kalimdor, enivrés par la puissance du Puits d'éternité, répondirent à l'appel du titan déchu Sargeras et ouvrirent un passage à la Légion ardente. Malfurion Hurlorage et la résistance kaldorei brisèrent ce passage grâce à l'Âme des dragons et rejetèrent Sargeras dans le Néant distordu, mais l'effondrement du Puits brisa le monde lui-même. L'antique Kalimdor sombra dans le feu et les flots ; des continents en ruine surgirent du naufrage, et le cœur englouti des terres devint la Grande mer, où le Maelström tourbillonne là où se dressait autrefois le Puits.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar est une terre rouge et crevassée, faite d'escarpements et de canyons, sèche et brûlante, pauvre en eau comme en verdure.",
		full = "Durotar est une terre rouge et crevassée, faite d'escarpements et de canyons, sèche et brûlante, pauvre en eau comme en verdure. Les orcs y trouvent une beauté âpre qui leur rappelle Draenor, et c'est ici, après le mont Hyjal, que Thrall mena son peuple pour bâtir une nouvelle patrie, qu'il nomma d'après son père assassiné, Durotan. La contrée avait appartenu aux hurans Tranchecrin avant que la Horde ne les en chasse.\n\nCette paix ne dura guère. Le grand amiral Daelin Portvaillant, héros de la deuxième guerre et nullement ami des orcs, lança une grande flotte de l'Alliance contre Durotar, résolu à écraser la Horde avant qu'elle ne puisse s'enraciner. Sa fille Jaina en décida autrement : à Theramore, elle se retourna contre son propre père pour combattre aux côtés de Thrall, et Daelin périt dans la bataille avant que tous deux aient pu se réconcilier. En remerciement de sa loyauté, Thrall laissa les soldats de Jaina se retirer indemnes à Theramore.\n\nLes trolls Darkspear arrivèrent sur la côte de Durotar en exilés, non en colons de leur plein gré. Trahis par l'un des leurs, le sorcier Zalazane, ils furent chassés de leur foyer des îles de l'Écho et bâtirent le village de pêcheurs de Sen'jin sur le rivage du continent, sans jamais pouvoir reprendre ce que Zalazane leur avait pris.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "Pendant des centaines d'années, les taurens n'eurent aucune terre à eux, pourchassés à travers Kalimdor par des pillards centaures qui dispersèrent leurs tribus en campements errants.",
		full = "Pendant des centaines d'années, les taurens n'eurent aucune terre à eux, pourchassés à travers Kalimdor par des pillards centaures qui dispersèrent leurs tribus en campements errants. Lorsque Thrall et ses orcs débarquèrent sur ces rivages, Cairne Bloodhoof vit en eux des esprits frères, honorables et forts. Escorté par les orcs et fort de leur appui, Cairne mena son peuple dans cette vallée abritée, ceinte de montagnes de toutes parts, et là, sa tribu Bloodhoof chassa enfin les centaures des prairies et les fit siennes.\n\nSur le plateau qui dominait la plaine, Cairne bâtit Thunder Bluff, un refuge ouvert aux taurens de toutes les tribus, et avec le temps, les peuples dispersés s'unirent sous son autorité.\n\nLes pâturages restent verts, les plateaux étendent toujours leurs longues ombres sur le village Bloodhoof, et chaque tauren qui atteint l'âge adulte doit encore s'aventurer dans les plaines sauvages pour faire ses preuves lors de la Grande chasse, comme le firent ses ancêtres.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "Les Tarides",
		short = "La poussière d'ici n'a pas toujours été poussière. C'était autrefois une forêt, entretenue par les Kaldorei qui y élevèrent l'avant-poste de Then'Ralore, et l'on dit que le demi-dieu Lo'Gosh s'y dressa contre la Légion ardente pendant la guerre des Anciens.",
		full = "La poussière d'ici n'a pas toujours été poussière. C'était autrefois une forêt, entretenue par les Kaldorei qui y élevèrent l'avant-poste de Then'Ralore, et l'on dit que le demi-dieu Lo'Gosh s'y dressa contre la Légion ardente pendant la guerre des Anciens. La Grande fracture mit fin à tout cela, et la verte vallée devint la plaine brûlée de soleil qu'elle est aujourd'hui.\n\nDes générations durant, les taurens errèrent dans ces plaines, chassant le kodo et le lézard-tonnerre, en quête de la sagesse de la Terre-mère, sans cesse harcelés par des centaures qui les traquaient pour le plaisir. Ils se défendaient, mais jamais par amour de la guerre ; quand venaient les hommes-chevaux, ils levaient le camp et partaient plutôt que de gaspiller des vies. Une année de paix, une année de guerre : telle était la vie des taurens, jusqu'au jour où les orcs de Thrall et les trolls Darkspear débarquèrent et marchèrent avec les taurens Bloodhoof contre les centaures. Après la chute de la Légion au mont Hyjal, Thrall revendiqua l'est des Tarides, chassa les hurans Tranchecrin et nomma cette terre Durotar, élevant Orgrimmar pour en faire sa capitale.\n\nLa terre garde aussi des chagrins plus anciens : on raconte qu'un homme nommé Dethorin trouva sa bien-aimée Allurana dans les bras d'un autre, et que son cri arracha du sable la hache Killmaim, la lame même dont il s'était servi pour la tuer.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Après que la Fracture eut brisé le monde, les elfes de la nuit qui restaient se retirèrent délibérément du reste du monde.",
		full = "Après que la Fracture eut brisé le monde, les elfes de la nuit qui restaient se retirèrent délibérément du reste du monde. Chez les humains, Kalimdor ne survécut qu'à l'état de légende, une terre qui se serait brisée et aurait sombré sous les flots, sans qu'ils en connaissent ni l'emplacement ni la forme.\n\nMais elle n'était pas entièrement perdue. Les elfes de la nuit rendirent visite aux Quel'dorei dans les années qui suivirent, si bien que seuls les hauts-elfes de Quel'Thalas savaient que la légende était vraie.\n\nMême lorsque vint la troisième guerre, la plupart des humains refusaient encore de croire à l'existence de Kalimdor, et l'ambassadeur du Kirin Tor à la cour du roi Terenas comptait lui-même parmi les sceptiques. Seuls quelques-uns écoutèrent l'avertissement de Medivh et firent voile vers l'ouest, parmi eux la nouvelle Horde de Thrall, suivie de l'expédition de Jaina Proudmoore. Ce qu'ils découvrirent n'était pas une légende mais un continent entier, de la glace au nord, du désert au sud, et entre les deux, des elfes de la nuit qui tenaient toujours les forêts.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Royaumes de l'est",
		short = "Les Royaumes de l'est n'ont pas toujours été plusieurs terres.",
		full = "Les Royaumes de l'est n'ont pas toujours été plusieurs terres. Ils faisaient jadis partie d'un seul continent, avant que la Grande fracture ne déchire le monde et ne laisse derrière elle les fragments brisés que l'on nomme aujourd'hui Azeroth, Khaz Modan et Lordaeron, Quel'Thalas s'accrochant au nord de cette dernière terre morcelée, sans que l'on sache encore aujourd'hui si elle forme un lieu à part entière ou un simple recoin d'une autre.\n\nÀ travers ces fragments, les montagnes de Khaz Modan et les Carmines se dressent comme une échine au cœur du continent, et autour d'elles subsistent les peuples anciens : les nains et les gnomes dans leurs salles profondes, les humains dans leurs royaumes, les hauts-elfes dans leurs forêts, et désormais les Réprouvés, relevés là où vivait autrefois le peuple de Lordaeron. Orcs, gobelins, nagas et ogres ont eux aussi trouvé le chemin de ces terres, bien qu'aucun d'eux n'y soit né.\n\nLes cicatrices de cette première fracture restent la vérité de ces lieux. Chaque frontière, chaque détroit, chaque étendue de terre engloutie entre un royaume et le suivant se souvient que les Royaumes de l'est furent jadis un tout, et qu'ils ne le sont plus.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Montagnes d'Alterac",
		short = "La pluie ne cesse jamais tout à fait de tomber sur ces sommets, et le ciel au-dessus d'eux est toujours gris. Ces montagnes couronnaient jadis la cité-État d'Alterac, qui dominait une grande partie des terres du nord, et abritaient en outre Dalaran.",
		full = "La pluie ne cesse jamais tout à fait de tomber sur ces sommets, et le ciel au-dessus d'eux est toujours gris. Ces montagnes couronnaient jadis la cité-État d'Alterac, qui dominait une grande partie des terres du nord, et abritaient en outre Dalaran. L'une et l'autre ont disparu, et ce qu'il en reste explique pourquoi si peu osent s'aventurer jusqu'ici.\n\nÀ la fin de la deuxième guerre, l'Alliance de Lordaeron apprit que les seigneurs d'Alterac avaient traité en secret avec la Horde, et envoya une armée dans ces montagnes frapper les traîtres jusque dans leur propre foyer. La cité tomba, son peuple fut dispersé ou emprisonné, et sa lignée ne retrouva jamais son trône. Un prince plus tardif de cette maison déchue, Aliden Perenolde, s'éleva plutôt en seigneur des brigands, rassemblant les proscrits et les vindicatifs au sein du Syndicat, une compagnie de voleurs qui tient toujours Strahnbrad et parcourt ces pentes dans l'espoir de reconquérir ce que sa famille a perdu.\n\nAujourd'hui, les ruines de la cité d'Alterac appartiennent aux ogres Cassecrête, et le Syndicat tient une bonne partie de ce que les ogres ne tiennent pas.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Hautes-terres d'Arathi",
		short = "Le roi Thoradin vint dans cette contrée aride parce qu'un rêve lui avait annoncé que son peuple y prospérerait, et il y éleva Strom, la première capitale d'un Arathor unifié.",
		full = "Le roi Thoradin vint dans cette contrée aride parce qu'un rêve lui avait annoncé que son peuple y prospérerait, et il y éleva Strom, la première capitale d'un Arathor unifié. Le sol sec lui servit de mur d'épines, privant les trolls des forêts amani du couvert nécessaire à leurs embuscades, et il éleva de surcroît une seconde muraille. Pendant mille ans, Strom demeura au cœur de l'empire, jusqu'à ce que ses maisons nobles s'éloignent vers des terres plus riches et que les derniers descendants de Thoradin partent fonder Stormwind. Ce qui resta devint Stromgarde, tenue depuis lors par la lignée des Trollemort.\n\nStromgarde est tombée depuis, submergée par les ogres et le Syndicat, et ses survivants ont été chassés du donjon jusqu'à un canyon qu'ils appellent désormais le Refuge de l'Ornière. Non loin se dresse Trépas-d'Orgrim, jadis un camp où l'humanité tenait ses prisonniers orcs en cage, aujourd'hui tenu par les orcs eux-mêmes et rebaptisé en l'honneur d'Orgrim Marteau du Destin.\n\nLa grande muraille de Thoradin s'est effondrée en une ruine béante, et son donjon gît brisé et disputé, toujours convoité par les ogres, le Syndicat et les derniers soldats d'un royaume qui tente de le reprendre.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Terres ingrates",
		short = "Les Terres ingrates sont un désert crevassé de terre sèche, de rochers épars et de canyons sinueux, enserré de montagnes de toutes parts. Presque rien n'y survit, hormis les coyotes, les cougars et les busards.",
		full = "Les Terres ingrates sont un désert crevassé de terre sèche, de rochers épars et de canyons sinueux, enserré de montagnes de toutes parts. Presque rien n'y survit, hormis les coyotes, les cougars et les busards.\n\nDans les confins du nord gisent les ruines d'Uldaman, œuvre des anciens terrestres. Lorsqu'elle fut mise au jour, elle livra les premiers indices sur les nobles origines des nains, et les prospecteurs d'Ironforge affluèrent pour fouiller la ruine en quête d'artefacts des Titans. Mais les troggs Cavepierre, réveillés après des millénaires de sommeil, massacrèrent les explorateurs et défendent désormais avec sauvagerie leur cité volée. Une grande forteresse Sombrefer se dresse juste au sud d'Uldaman, et ses nains y guerroient contre les ogres de la tribu Dustbelcher et contre les drakes qui nichent parmi les rejetons des dragons noirs, à l'est.\n\nPlus tard, Kargath fut fondée ici, seul avant-poste de la Horde en Khaz Modan, afin que les orcs puissent surveiller leurs cousins renégats de Blackrock. Le chef de guerre Thrall en personne envoya le corps expéditionnaire de Kargath traquer Rend Blackhand.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Terres foudroyées",
		short = "Les Terres foudroyées portent bien leur nom. L'argile rouge qu'on y foule était jadis une terre fauve, qui faisait partie d'un sombre marécage nommé le Noir marécage, avant que la Horde orque n'y ouvre de force la Porte des ténèbres pour se déverser sur Azeroth.",
		full = "Les Terres foudroyées portent bien leur nom. L'argile rouge qu'on y foule était jadis une terre fauve, qui faisait partie d'un sombre marécage nommé le Noir marécage, avant que la Horde orque n'y ouvre de force la Porte des ténèbres pour se déverser sur Azeroth. La magie qui s'échappa ce jour-là brûla le sol jusqu'à le rougir et le tua pour de bon. Rien n'y pousse plus désormais, hormis de robustes broussailles du désert, et de robustes créatures du désert : basilics, scorpions, hyènes.\n\nL'archimage Khadgar et le Kirin Tor élevèrent le Rempart-du-Néant pour surveiller les ruines de la porte et veiller à ce que rien ne la franchisse plus jamais. La paix dura deux ans, jusqu'à ce que la Horde de Draenor rouvre la Porte et assiège la forteresse. Quand le rituel de Ner'zhul commença à déchirer Draenor, Khadgar et les autres mages se servirent du Crâne de Gul'dan pour faire voler en éclats, depuis l'autre côté, le cadre de pierre de la Porte, rompant pour de bon le pont entre les mondes.\n\nAujourd'hui, les mages et les paladins du Rempart-du-Néant montent toujours leur sombre garde sur la Porte morte, une communauté soudée et sans humour qui ne fait confiance à personne et ne pardonne aucune défaillance, seul abri que l'on puisse trouver sur une terre où les orages venus de la mer orientale ruissellent sur le sol calciné avant d'avoir pu lui faire le moindre bien.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Clairières de Tirisfal",
		short = "Le ciel des clairières de Tirisfal est d'un vert maladif depuis des années, et les arbres s'accrochent au peu de vie que la peste leur a laissé.",
		full = "Le ciel des clairières de Tirisfal est d'un vert maladif depuis des années, et les arbres s'accrochent au peu de vie que la peste leur a laissé. C'étaient jadis de paisibles fermes sous le règne du roi Terenas, où des générations vivaient tranquillement parmi les moulins et les champs de citrouilles. Tout cela prit fin lorsqu'Arthas Menethil mit Lordaeron à sac et répandit la peste à travers les campagnes, tuant ses habitants et les relevant en esclaves du roi-liche. Des fosses communes marquent encore les lieux où les morts étaient trop nombreux pour être enterrés dignement. C'est près de la ferme des Balnir, des mois plus tard, que Sylvanas Windrunner retourna ses banshees contre Arthas et planta une flèche empoisonnée dans le chevalier de la mort, avant que les squelettes de Kel'Thuzad ne la repoussent.\n\nDe cette ruine naquirent les Réprouvés, les morts libres de Sylvanas, qui revendiquèrent cette terre comme la leur. Leurs ennemis ne l'ont jamais quittée : la Croisade écarlate tient le vieux Monastère écarlate au nord, des fanatiques qui brûlent et traquent tout ce qui n'est pas humain.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Forêt des Pins argentés",
		short = "La forêt des Pins argentés, ou simplement les Pins argentés, est un bois vaste et ancien qui longe la côte ouest escarpée de Lordaeron. Le terrain y va du plat au vallonné, niché au milieu de montagnes plus hautes encore.",
		full = "La forêt des Pins argentés, ou simplement les Pins argentés, est un bois vaste et ancien qui longe la côte ouest escarpée de Lordaeron. Le terrain y va du plat au vallonné, niché au milieu de montagnes plus hautes encore. La forêt est d'un silence inquiétant, hormis quelques hurlements contre nature qui résonnent parfois entre les arbres. Des surplombs moussus frissonnent sous la brise froide, et les arbres sont tous malades ou mourants. Des fermes délabrées et des mines abandonnées parsèment la contrée, où logent désormais les plus sombres habitants des bois.\n\nCe bois est hanté et sauvage, reconnaissable à ses hauts pins à l'écorce argentée qui dominent des buttes herbeuses. L'Alliance protégeait jadis la forêt des Pins argentés, du temps où elle était verdoyante et pleine de vie. Aujourd'hui, les lieux sont drapés de brumes spectrales. Les Réprouvés contrôlent le nord de la forêt et affrontent sans cesse les misérables gnolls Poil-putride. Ce qui reste de la population humaine tient le sud de la forêt, mais ces gens sont aux abois et leurs forces trop dispersées. Dalaran envoie fréquemment des expéditions dans les Pins argentés pour défendre ces populations et étudier la peste des morts-vivants et la malédiction des worgens, un mal mystérieux qui transforme ses victimes en worgens lycanthropes assoiffés de sang au lever de la lune.\n\nGilnéas et les contreforts d'Hillsbrad bordent la forêt au sud, tandis que les clairières de Tirisfal s'étendent au nord. Le lac Lordamere forme la frontière orientale des Pins argentés.\n\nBien que le territoire appartienne aux Réprouvés, leur prétention est contestée par les sorciers de Dalaran et par les agents du Fléau, qui se sont emparés de certains champs et domaines en ruine. Les gnolls Poil-putride opèrent depuis la mystérieuse île de Fenris et attaquent férocement quiconque ose approcher de leurs affaires. Au sud-ouest se trouve Bois-du-Bûcher, dont les habitants sont tombés sous la malédiction de l'archimage Arugal et se changent la nuit en worgens assoiffés de sang. Arugal a élu domicile dans les sombres tours voisines du donjon d'Ombrecroc.\n\nLa forêt des Pins argentés est souvent le théâtre de combats, car les forces de l'Alliance venues de Southshore se rendent dans ces bois abandonnés pour attaquer le Sépulcre ou pénétrer dans Ombrecroc. C'est la lisière de la patrie des Réprouvés, et le point le plus au sud où l'on voit les effets de la peste des morts-vivants sur la végétation.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Maleterres de l'ouest",
		short = "C'étaient autrefois les plus belles terres agricoles du nord de Lordaeron, boisées et verdoyantes, qui remplissaient les greniers du royaume depuis Andorhal et étaient gouvernées depuis le manoir de Hearthglen.",
		full = "C'étaient autrefois les plus belles terres agricoles du nord de Lordaeron, boisées et verdoyantes, qui remplissaient les greniers du royaume depuis Andorhal et étaient gouvernées depuis le manoir de Hearthglen. Cette prospérité devint l'arme qui servit à les détruire.\n\nSuivant le dessein du roi-liche, le culte des Damnés transporta ses énergies pestilentielles vers le sud dans des chaudrons portatifs, les cachant dans des villages de fidèles et installant les quatre plus grands dans les champs mêmes d'Andorhal. Le grain lui-même fut contaminé, et il partit à travers Lordaeron dans des chariots que personne ne songea à inspecter. Ceux qui mangèrent leur propre pain tombèrent malades, moururent et se relevèrent en esclaves du roi-liche. Les forêts ne s'en remirent jamais. Les pins se dressent, gris aux aiguilles brunies, sous un voile de brume maladive, leurs troncs gonflés d'excroissances tumorales.\n\nLe peu d'ordre qui subsiste fut sauvé après l'effondrement du royaume, lorsque la Croisade écarlate s'empara du donjon de Mardenholde à Hearthglen et partit de là à l'assaut des morts-vivants qui tenaient le reste de la contrée. Au milieu de tout cela, un seul lieu conserve un semblant de paix : le tombeau d'Uther, consacré à Uther le Porteur de Lumière, une terre que le fléau n'a jamais touchée.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Maleterres de l'est",
		short = "Cette terre était autrefois cultivée : les villages de la Sylve de l'Est s'y dispersaient autour de Stratholme, deuxième cité de Lordaeron. Il n'en reste rien.",
		full = "Cette terre était autrefois cultivée : les villages de la Sylve de l'Est s'y dispersaient autour de Stratholme, deuxième cité de Lordaeron. Il n'en reste rien. Le sol est désormais brun et malade, les arbres ont enflé jusqu'à devenir des champignons, et l'air est chargé d'une épaisse brume orangée.\n\nC'est à Stratholme que vint le prince Arthas, traquant la source d'une peste qui avait déjà emporté les habitants. Le seigneur Uther, maître de la Main d'argent, refusa de le laisser purger la ville. Arthas lui retira son commandement, dissout la Main d'argent sur-le-champ et passa lui-même les habitants de Stratholme au fil de l'épée plutôt que de les laisser se relever au service du Fléau. Il ne s'arrêta pas là : il poursuivit le seigneur de l'effroi Mal'Ganis jusque dans le Nord, en revint chevalier de la mort et tua son propre père, mettant fin au royaume de Lordaeron.\n\nAlexandros Mograine leva une croisade parmi les restes de la Main d'argent pour reprendre la ruine, s'emparant de la Main de Tyr et de la moitié de Stratholme, avant que sa mort ne scinde son ordre entre l'Aube d'argent et la Croisade écarlate, qui tient toujours ces champs, livrant au Fléau une guerre sans fin et n'accueillant personne d'autre.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Contreforts d'Hillsbrad",
		short = "Le sol d'Hillsbrad est riche et ses collines sont vertes, et les voyageurs disent que c'est à cela que ressemblait tout Lordaeron avant l'arrivée de la peste.",
		full = "Le sol d'Hillsbrad est riche et ses collines sont vertes, et les voyageurs disent que c'est à cela que ressemblait tout Lordaeron avant l'arrivée de la peste. C'est là sa cruauté autant que son réconfort : la terre se souvient de ce qui a été perdu partout ailleurs, tandis que ceux qui la tiennent livrent la même guerre qui a ruiné le reste.\n\nAu début de la deuxième guerre, des pillards orcs frappèrent ses villes côtières, et Orgrim Marteau du Destin en personne chevaucha contre le donjon de Durnholde pour libérer Zul'jin de ses cellules. Des décennies plus tard, ce fut Thrall qui traversa ces collines, rassemblant les clans orcs dispersés avant de se glisser de nuit dans Southshore pour voler ses navires et emmener la nouvelle Horde de l'autre côté de la mer, jusqu'à Kalimdor.\n\nCe que les orcs avaient commencé, les Réprouvés l'ont poursuivi. Ils ont fait de Moulin-de-Tarren leur possession la plus méridionale et l'ont transformé en base d'opérations contre les humains de Southshore et des champs d'Hillsbrad, qui tenaient bon pour l'Alliance.\n\nDes bois de pins parsèment désormais les terres cultivées, et des routes traversent encore les pâturages vers les lugubres colonies réprouvées du nord, comme si la terre elle-même attendait encore de voir quel camp la gardera.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "Les Hinterlands",
		short = "Après la guerre des Trois clans, les nains Marteau-hardi abandonnèrent leurs tunnels de Grim Batol et vinrent vers le nord, bâtissant leurs demeures à l'air libre, au Nid-de-l'Aigle.",
		full = "Après la guerre des Trois clans, les nains Marteau-hardi abandonnèrent leurs tunnels de Grim Batol et vinrent vers le nord, bâtissant leurs demeures à l'air libre, au Nid-de-l'Aigle. Ils se détournèrent de la pierre et de la forge pour se tourner vers le ciel et les ailes, se liant si étroitement aux gryphons sauvages de la région qu'ils élevèrent un grand gryphon de pierre dans leur propre cité pour honorer ce lien. Les trolls des forêts qui tenaient déjà cette terre, vestiges du puissant empire Amani, voyaient dans les nains des squatteurs installés sur une terre ancestrale, et attaquaient les aires chaque fois qu'ils le pouvaient.\n\nLorsque la Horde déferla pendant la deuxième guerre, le thane Kurdran Marteau-hardi et ses chevaucheurs, qui ignoraient jusque-là l'existence même de ces envahisseurs, fondirent du ciel sur les colonnes orques avec leurs marteaux chargés d'orage, les harcelant sans relâche. Orgrim Marteau du Destin espérait attirer les forces de l'Alliance dans les Hinterlands afin de frapper Quel'Thalas sans rencontrer d'opposition, mais Anduin Lothar perça son plan à jour et vint lui-même se ranger aux côtés de Kurdran ; ensemble, ils brisèrent les envahisseurs et les repoussèrent jusqu'aux montagnes d'Alterac. En reconnaissance, Kurdran promit l'aide de son peuple à l'Alliance.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "La neige recouvre profondément Dun Morogh, enclavé de toutes parts par les montagnes de Khaz Modan, et ses cols sont sans cesse surveillés par les troupes naines.",
		full = "La neige recouvre profondément Dun Morogh, enclavé de toutes parts par les montagnes de Khaz Modan, et ses cols sont sans cesse surveillés par les troupes naines. Avant d'appartenir à qui que ce soit d'autre, ces montagnes appartenaient aux trolls des glaces Frostmane, qui s'étaient installés dans la région après s'être séparés de l'empire Drakkari dans des temps reculés.\n\nTout changea lorsque les premiers gnomes sortirent d'Uldaman et mirent leur ingéniosité au service de leur survie, face au froid comme aux trolls, creusant des demeures fortifiées au plus profond des pics. Cinq cents ans plus tard, les nains sortirent à leur tour d'Uldaman, attirés par ces mêmes montagnes qu'ils avaient aperçues à l'horizon, et élevèrent Ironforge sous la plus haute d'entre elles. Trouvant les gnomes déjà installés non loin, les deux peuples nouèrent une amitié qui ne s'est jamais rompue : les nains prêtèrent leur force pour ériger Gnomeregan, les gnomes partagèrent les secrets de leurs machines. Ensemble, leurs armées brisèrent les trolls Frostmane et repoussèrent les survivants dans les collines, mettant fin pour de bon à l'emprise des trolls sur la contrée.\n\nGnomeregan n'est plus aujourd'hui qu'une ruine, et son peuple s'entasse dans Ironforge pour y trouver refuge.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Gorge des Vents brûlants",
		short = "C'était autrefois une terre verdoyante, qui faisait partie des Carmines, jusqu'à ce que le sol lui-même soit éventré il y a plus de deux cent trente ans.",
		full = "C'était autrefois une terre verdoyante, qui faisait partie des Carmines, jusqu'à ce que le sol lui-même soit éventré il y a plus de deux cent trente ans.\n\nPendant la guerre des Trois clans, le thane-sorcier Thaurissan, des nains Sombrefer, chercha une arme pour briser ses ennemis. Avec sept de ses nains les plus fidèles, il tendit la main sous le monde et fit appel à des puissances qui auraient dû rester endormies. Ce qui répondit n'était pas un serviteur mais un maître : l'antique Ragnaros, le seigneur du Feu. Son réveil arracha le mont Blackrock des entrailles de la terre, noircit le pays sur des lieues et réduisit en poussière, sous sa masse, Thaurissan, la capitale des Sombrefer. Les steppes calcinées du sud prirent le nom de Steppes ardentes ; cette vallée ravagée du nord devint la gorge des Vents brûlants.\n\nTous les Sombrefer ne restèrent pas fidèles à leur clan après la catastrophe. Un certain nombre d'entre eux firent sécession, se nommèrent la Confrérie du Thorium et bâtirent la Halte du Thorium au-dessus de la grande excavation que leurs anciens frères avaient creusée dans le fond de la vallée, observant d'en haut les travaux des Sombrefer.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Steppes ardentes",
		short = "Le ciel des Steppes ardentes ne perd jamais sa teinte rouge, éclairé par les éruptions sporadiques du mont Blackrock, et le sol ne refroidit jamais.",
		full = "Le ciel des Steppes ardentes ne perd jamais sa teinte rouge, éclairé par les éruptions sporadiques du mont Blackrock, et le sol ne refroidit jamais. Deux cents ans avant l'ouverture de la Porte des ténèbres, les nains Sombrefer vinrent ici, exilés d'Ironforge. Leur thane-sorcier, Thaurissan, chercha à invoquer des serviteurs élémentaires pour remporter la guerre des Trois clans contre les clans Bronzebeard et Marteau-hardi. Ce qui répondit n'était pas un serviteur mais Ragnaros, le seigneur du Feu, jadis banni par les Titans. Son arrivée fit fondre les montagnes alentour, dressa un volcan au cœur de l'explosion et anéantit les nains qui l'avaient invoqué. Ce qui s'étendait au nord de ce nouveau pic devint la gorge des Vents brûlants ; ce qui s'étendait au sud, les Steppes ardentes, marquées depuis lors.\n\nLes orcs s'installèrent sur les pentes du volcan pendant la première guerre et firent du pic Blackrock leur place forte durant la deuxième. Les orcs Blackrock y revinrent ensuite et y sont toujours, fidèles aux vieilles coutumes brutales d'avant la trêve de Thrall. Des dragons noirs aux ordres de Nefarian tiennent les niveaux supérieurs du pic, et l'on dit que Ragnaros rumine encore quelque part sous tout cela.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Forêt d'Elwynn",
		short = "Lorsque les orcs vinrent pendant la première guerre, des milliers d'entre eux traversèrent Elwynn pour encercler Stormwind, la coupant de tout sauf de la mer.",
		full = "Lorsque les orcs vinrent pendant la première guerre, des milliers d'entre eux traversèrent Elwynn pour encercler Stormwind, la coupant de tout sauf de la mer. Le chevalier champion Anduin Lothar mena les chevaliers de Stormwind dans une charge à travers la forêt même, frappant par surprise l'arrière-garde orque et la dispersant. Cela fit gagner du temps à la cité, mais pas assez. Le chef de guerre Blackhand prit bientôt Goldshire et Ruisselune, les dernières villes qui se dressaient entre la Horde et le roi, et le donjon de Stormwind fut mis à sac. Lothar conduisit les survivants jusqu'à la mer, puis vers Lordaeron, et les ruines de la cité appartinrent un temps au clan Foudreguerre. Des catapultes orques éparses gisent encore, brisées et pourrissantes, à travers la région, seuls souvenirs de cette occupation.\n\nLes vignes de Northshire, à l'est de la cité, faisaient jadis la fierté des fermiers de Stormwind. Quand la guilde des Maçons ne fut pas payée pour les années passées à rebâtir la capitale en ruine, et que les nobles la dissolurent plutôt que de régler leur dette, la fureur du maître de guilde Edwin VanCleef se propagea en émeutes qui coûtèrent la vie à la reine Tiffin Ellerian Wrynn et donnèrent naissance à la Confrérie défias. La Confrérie chassa les fermiers de Northshire et occupa ses champs.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Défilé de Deuillevent",
		short = "Le défilé de Deuillevent traverse les montagnes du centre d'Azeroth, reliant le bois de la Pénombre au marais des Chagrins. Il y a une vingtaine d'années, on le comptait encore parmi les Carmines.",
		full = "Le défilé de Deuillevent traverse les montagnes du centre d'Azeroth, reliant le bois de la Pénombre au marais des Chagrins. Il y a une vingtaine d'années, on le comptait encore parmi les Carmines.\n\nLa tour d'Ivoire de Karazhan, jadis siège du pouvoir du sombre sorcier Medivh, se dresse au centre de cette région déchiquetée et répand dans la terre une magie maléfique. Les arbres y sont pétrifiés et dénudés, et un vent terrible gémit à travers le canyon. Ogres, démons, morts-vivants et quelques bohémiens humains errent à l'intérieur, et des murmures prétendent qu'une force nouvelle s'est emparée de la tour d'Ivoire, et que les ogres et les démons sont sous son emprise.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Bois de la Pénombre",
		short = "Un manteau de nuit surnaturelle recouvre le bois de la Pénombre, et il ne s'est jamais levé.",
		full = "Un manteau de nuit surnaturelle recouvre le bois de la Pénombre, et il ne s'est jamais levé. Ce qui était autrefois une belle étendue de la forêt d'Elwynn n'est plus qu'une terre maudite et mourante : les arbres se sont tordus sous le brouillard noir, les morts se sont relevés de leurs tombes, et les worgens sont venus se faufiler avec les ténèbres elles-mêmes, attirés par les manigances liées à la Faux d'Élune. Les ogres qui poussent depuis le défilé de Deuillevent n'ont fait qu'aggraver la misère.\n\nLa protection de Stormwind a depuis longtemps cessé de signifier quoi que ce soit ici, et ceux qui restent ont appris à tenir bon sans elle. Leur milice, les Veilleurs, patrouille sur les routes et garde Darkshire contre tout ce qui bouge dans l'ombre : guerriers squelettes et goules, worgens féroces, et hommes des Défias par-dessus le marché.\n\nAu cœur du bois se trouve le cratère d'un volcan éteint depuis longtemps, enveloppé d'un crépuscule plus doux que l'obscurité qui l'entoure. On y trouve l'un des Grands arbres, dont les racines plongent vers le Rêve d'émeraude, et l'influence des druides endormis imprègne tout ce qui pousse aux alentours. Au-delà s'étendent des fermes abandonnées et les vastes tombes du cimetière de Colline-aux-Corbeaux, qui se remplit année après année depuis que les ténèbres sont tombées.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Les eaux du Loch Modan reposent dans un écrin de pierre grise, retenues par le barrage de Formepierre, un ouvrage d'ingénierie naine qu'aucune autre construction d'Azeroth n'a jamais égalé.",
		full = "Les eaux du Loch Modan reposent dans un écrin de pierre grise, retenues par le barrage de Formepierre, un ouvrage d'ingénierie naine qu'aucune autre construction d'Azeroth n'a jamais égalé. Les montagnes s'élèvent à pic de tous côtés, légèrement boisées de pins et de bouleaux, et le loch lui-même demeure immobile et paisible, comme si rien ne l'avait jamais troublé.\n\nLe loch fut pourtant un champ de bataille. Pendant la deuxième guerre, les orcs de la Horde déferlèrent sur la région et y livrèrent bataille contre l'Alliance. Ironforge tint bon. Ses nains repoussèrent les orcs et reprirent le Loch Modan, mais les débris de cette guerre ne furent jamais entièrement déblayés : catapultes brisées et balistes fracassées gisent encore, à demi englouties, sur le fond du lac et ses îles, seule preuve restante que ces eaux calmes furent un jour un lieu de carnage.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Les Carmines",
		short = "Les Carmines s'étendent à l'est de la forêt d'Elwynn, au nord-est du bois de la Pénombre et au sud des Steppes ardentes.",
		full = "Les Carmines s'étendent à l'est de la forêt d'Elwynn, au nord-est du bois de la Pénombre et au sud des Steppes ardentes.\n\nRégion idyllique de rivières tumultueuses, d'ormes majestueux et de reliefs qui s'élèvent, les Carmines sont sous la protection de Stormwind, bien qu'elles soient techniquement indépendantes depuis la deuxième guerre. Elles restent l'une des dernières régions paisibles d'Azeroth, dont les habitants, calmes et satisfaits, fournissent à Stormwind du bois, du poisson et des récoltes. Pourtant, cette paix est imparfaite : une troupe d'orcs Blackrock venue des Steppes ardentes tient le donjon de Guet-de-pierre, même si, pour l'instant, elle reste à l'écart. Comparées à la ruine de la Marche de l'Ouest, les Carmines tiennent encore debout.\n\nSur la rive nord du lac placide se dresse la ville de Lakeshire, assiégée par les gnolls et les orcs Blackrock descendus des collines environnantes. Au sud, le carrefour appelé les Trois chemins relie Lakeshire à Elwynn et au bois de la Pénombre, et, par la grand-route de la Crête du lac, au donjon de Guet-de-pierre, une route tenue par des dragonnets, des gnolls, des murlocs et des bêtes sauvages.\n\nLa surface du lac paraît assez calme, mais des murlocs rôdent en dessous, et la rumeur persiste qu'un monstre marin vit dans ses profondeurs.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Vallée de Strangleronce",
		short = "La vallée de Strangleronce est une vaste jungle au sud du bois de la Pénombre. Les trolls de la jungle patrouillent dans cette forêt tropicale étouffante, les nagas chassent le long de ses côtes, et les lianes étrangleuses comme les bêtes rendent tout voyage périlleux.",
		full = "La vallée de Strangleronce est une vaste jungle au sud du bois de la Pénombre. Les trolls de la jungle patrouillent dans cette forêt tropicale étouffante, les nagas chassent le long de ses côtes, et les lianes étrangleuses comme les bêtes rendent tout voyage périlleux.\n\nLa vallée fut jadis le cœur de l'empire Gurubashi, dont les grandes cités s'élevaient dans toute la région. Après la chute de l'empire, ces cités tombèrent en ruine, bien que des trolls vivent encore parmi elles. Zul'Gurub, au nord-est, était autrefois la capitale des Gurubashi.\n\nBaie-du-Butin était à l'origine une petite ville portuaire fondée par des humains, jusqu'à ce que les trolls l'envahissent. Les gobelins du cartel Gentepression chassèrent plus tard les trolls de la crique et se l'approprièrent, en faisant leur centre d'opérations dans les Royaumes de l'est.\n\nAu nord se dresse un camp élevé par l'expédition du colonel Kurzen. C'est là que l'esprit du colonel fut capturé par un mage ogre, Mai'Zoth, qui se servit d'un artefact appelé l'Œil de l'esprit pour plier la volonté de Kurzen et commander ses hommes. Un certain nombre de soldats de Kurzen se rebellèrent contre leur commandant possédé et s'enfuirent vers l'ouest, où ils fondèrent un camp rebelle pour le défier.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Marais des Chagrins",
		short = "Sous l'eau noire du marais repose un temple plus ancien que le chagrin qui a donné son nom à ce lieu.",
		full = "Sous l'eau noire du marais repose un temple plus ancien que le chagrin qui a donné son nom à ce lieu. Lorsque l'empire Gurubashi tomba, une bande renégate de trolls appelés les Atal'ai s'enfuit dans le marais et éleva le temple d'Atal'Hakkar, où ils pratiquèrent de macabres rites pour ramener dans le monde leur sombre loa, Hakkar l'Écorcheur d'âmes. Leur magie tordit les plantes et les bêtes autour du temple, jusqu'à ce que la corruption ne puisse plus passer inaperçue. Ysera, maîtresse des rêves, apprit les ambitions du culte et retourna sa puissance contre eux, engloutissant le temple sous la plus vaste des tourbières avant qu'Hakkar ne puisse revenir. Mais elle ne se fiait pas aux trolls pour renoncer à jamais à leur dieu. Elle chargea son consort Eranikus et une armée de dragons verts de monter une garde éternelle sur la ruine, afin qu'elle ne puisse plus jamais servir à déchaîner un tel mal sur le monde. Des drakônides verts patrouillent encore ces marais sur son ordre, et le temple englouti reste scellé sous les eaux, surveillé plutôt que détruit.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Marche de l'Ouest",
		short = "Le vent souffle désormais sans obstacle sur les champs de la Marche de l'Ouest, car plus rien de haut ne s'y dresse pour l'arrêter. C'était autrefois le grenier de Stormwind, qui nourrit le jeune royaume pendant des générations.",
		full = "Le vent souffle désormais sans obstacle sur les champs de la Marche de l'Ouest, car plus rien de haut ne s'y dresse pour l'arrêter. C'était autrefois le grenier de Stormwind, qui nourrit le jeune royaume pendant des générations.\n\nLorsque la guilde des Maçons ne fut pas payée pour avoir rebâti Stormwind après la deuxième guerre, et que la garde se retourna contre ses protestations, le maître de guilde Edwin VanCleef entraîna ses hommes dans la clandestinité, au fond des campagnes, plutôt que d'affronter la justice du roi Varian. Ils y devinrent la Confrérie défias, et sous une grange de Ruisselune, VanCleef découvrit un vieux réseau de mines assez profond pour cacher la construction d'une arme destinée à incendier Stormwind depuis la mer. Il chassa les fermiers, engagea des gnolls Riverpaw pour tenir la contrée, et fit brûler les champs et saler la terre par ses hommes afin que plus rien n'y pousse.\n\nStormwind, ses coffres vidés, laissa la Marche de l'Ouest se débrouiller seule. Seul Gryan Stoutmantle répondit à l'appel, levant la milice du Peuple à la Colline des sentinelles quand aucune armée ne vint.\n\nLes champs qu'il avait salés ne l'ont pas pardonné à la Marche de l'Ouest. L'herbe pousse encore jaune et clairsemée là où le blé montait jadis jusqu'aux épaules.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Les Paluns",
		short = "Un marécage gris et froid s'étend en contrebas du barrage, la brume couvrant ses rivières et ses étangs, cerné de montagnes sur trois côtés et ouvert sur la mer à l'ouest.",
		full = "Un marécage gris et froid s'étend en contrebas du barrage, la brume couvrant ses rivières et ses étangs, cerné de montagnes sur trois côtés et ouvert sur la mer à l'ouest. Des décombres y sont éparpillés, vestiges des forteresses naines qui tenaient jadis ce terrain. Ce sont désormais les murlocs, les bêtes sauvages et des orcs renégats qui le tiennent, et le port de Menethil est le seul véritable point d'appui de l'Alliance dans la région.\n\nCe port n'a pas toujours appartenu à l'Alliance. Au début de la deuxième guerre, Orgrim Marteau du Destin construisit sa flotte d'invasion sur un îlot de la baie de Baradin, afin que ses navires puissent frapper les côtes de Lordaeron sans affronter ses défenses terrestres. Les Paluns en payèrent le prix : orcs et dragons se nourrirent abondamment de la contrée, et le gibier se fit rare. Après la guerre, le port fut reconstruit et rebaptisé port de Menethil, en l'honneur de Terenas Menethil II.\n\nLa chute de Grim Batol vint ensuite. Le vol draconique rouge, asservi là-bas par le clan Gueule-de-dragon, se retourna contre ses geôliers une fois libéré, et le clan fut brisé, ses survivants dispersés dans la nature. Alexstrasza jugea que c'était à son vol qu'il incombait de garder la montagne scellée, et depuis lors, des dragons rouges veillent sur elle.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Lorsque Malfurion Hurlorage disparut dans le Rêve d'émeraude, l'archidruide Fandral Staghelm prit sa place à la tête du Cercle cénarien et convainquit le Cercle des Anciens que le temps était venu de faire pousser un nouvel Arbre-Monde et de reconquérir l'immortalité que les elfes de la nuit avaient perdue.",
		full = "Lorsque Malfurion Hurlorage disparut dans le Rêve d'émeraude, l'archidruide Fandral Staghelm prit sa place à la tête du Cercle cénarien et convainquit le Cercle des Anciens que le temps était venu de faire pousser un nouvel Arbre-Monde et de reconquérir l'immortalité que les elfes de la nuit avaient perdue. Dans la Mer voilée, ils firent croître Teldrassil, la couronne de la terre, et bâtirent Darnassus dans ses branches. Mais Nozdormu, qui avait béni le premier Arbre-Monde, refusa de bénir celui-ci, jugeant ce vœu arrogant, et l'immortalité que cherchaient les elfes de la nuit ne vint jamais.\n\nAvec le temps, les terres au sommet de Teldrassil tombèrent sous l'emprise d'une présence sinistre. Les furbolgs et les grells de ses forêts devinrent fous, des satyres apparurent parmi les arbres, et les grandes tortues et les batteurs qui nageaient autrefois dans les eaux entourant l'arbre s'enfuirent pour venir s'échouer et mourir sur les rivages de Sombrivage. La source de cette corruption demeure un mystère, et Malfurion n'est pas revenu du Rêve pour la rechercher.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Sombrivage",
		short = "Une brume grise s'étend le plus souvent le long de cette côte, et les elfes de la nuit y voient depuis longtemps un avertissement.",
		full = "Une brume grise s'étend le plus souvent le long de cette côte, et les elfes de la nuit y voient depuis longtemps un avertissement. La pluie et la roche rendent la contrée inhospitalière, et toutes les tentatives pour s'y établir au-delà du comptoir d'Auberdine sont restées vaines.\n\nIl y a dix mille ans, les cités jumelles d'Ameth'Aran et de Bashal'Aran se dressaient ici, gouvernées par Athrikus Narassin. Lorsque la guerre des Anciens brisa le monde et que survint la Grande fracture, Athrikus jura à son peuple qu'il le sauverait. Il tint sa promesse à la lettre mais en trahit l'esprit : il lia leurs âmes à des gemmes d'âme, leur affirmant que c'était la vie éternelle, alors qu'en vérité il les vidait pour nourrir sa propre puissance. Les cités tombèrent en ruine, et ce qui erre aujourd'hui parmi leurs pierres n'a pas entièrement trouvé le repos.\n\nAprès la troisième guerre, Fandral Staghelm conduisit les druides du Cercle cénarien à Sombrivage et planta un nouvel Arbre-Monde, Teldrassil, sur ce rivage.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Orneval",
		short = "Orneval est une forêt antique, pleine de vieux arbres et de vieille magie, que l'on n'a jamais cessé de se disputer.",
		full = "Orneval est une forêt antique, pleine de vieux arbres et de vieille magie, que l'on n'a jamais cessé de se disputer.\n\nLes orcs du clan Warsong vinrent d'abord ici en bûcherons. Des gobelins menés par Neeloc Greedyfingers dépouillèrent les arbres jusqu'à ce que les furbolgs de la région les repoussent, et Grommash Hurlenfer écrasa à son tour les furbolgs et les Sentinelles pour conserver l'aide des gobelins. Cénarius vint en personne restaurer ce qui avait été abattu, et il le paya de sa vie : les maîtres de la Légion ardente firent de sa confiance un piège, et Grommash l'abattit.\n\nLe pire survint lorsque la Légion marcha sur Orneval avec toutes ses forces. Les infernaux d'Archimonde tombèrent du ciel en flammes, et morts-vivants et démons déferlèrent depuis l'est, submergeant les armées divisées des elfes de la nuit, des orcs et des humains avant de poursuivre vers le mont Hyjal. Tyrande Whisperwind tira Malfurion du Rêve d'émeraude, et il trouva la forêt dont il se souvenait dévorée par le gangrefeu et une flétrissure suffocante.\n\nCette vieille rivalité n'a jamais pris fin. Les elfes de la nuit tiennent toujours Astranaar et leurs refuges épars ; la Horde a enfoncé ses camps Warsong loin dans le sud et l'est, abattant du bois et repoussant les Sentinelles. Aucun des deux camps n'a jamais achevé la lutte pour ces bois.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Mille pointes",
		short = "Le canyon s'enfonce, profond et aride, son fond perdu parmi d'immenses plateaux, jusqu'à ce qu'il s'ouvre à l'est sur les Salines, une grande étendue de sel sous un vaste ciel.",
		full = "Le canyon s'enfonce, profond et aride, son fond perdu parmi d'immenses plateaux, jusqu'à ce qu'il s'ouvre à l'est sur les Salines, une grande étendue de sel sous un vaste ciel. Le lever du soleil, vu depuis le poste de Librevent ou depuis les hauteurs entourant la cime de Noir-nuage, est un spectacle magnifique au-dessus d'une contrée si désolée. Le druide Quentin s'est demandé si l'âpre sécheresse de ces lieux, si proche de la jungle luxuriante de Féralas voisine, était bien naturelle, ou si elle ne portait pas plutôt la marque d'une étrange magie exercée sur la terre.\n\nLes hauts plateaux appartiennent aux taurens, et le poste de Librevent est leur place forte parmi eux. Ils n'ont pas conservé ce territoire sans combat. Les centaures de la région les harcelaient, et pis encore, leurs propres frères de la tribu Totem sinistre se retournèrent contre eux, si bien que les taurens du poste de Librevent durent combattre tribu contre tribu pour les hautes terres. Ce n'est qu'avec l'aide de la Horde qu'ils repoussèrent les centaures et les Totem sinistre.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Les Serres-Rocheuses",
		short = "Le pic des Serres-Rocheuses a toujours appartenu aux esprits avant d'appartenir à aucun peuple.",
		full = "Le pic des Serres-Rocheuses a toujours appartenu aux esprits avant d'appartenir à aucun peuple. Les elfes de la nuit y entretiennent un refuge et une clairière à son sommet, en communion avec la nature, et les taurens le tiennent eux aussi pour sacré, car c'est là que l'Oracle immortel observait jadis les fils du destin que tissait la Terre-mère. La légende raconte que les premiers taurens à s'installer dans ces montagnes portèrent des totems enflammés jusqu'aux plus hauts escarpements, allumant des feux de joie en l'honneur d'An'she pour repousser les ténèbres accrochées à la pierre.\n\nPlus bas sur la montagne, Élune bénit il y a longtemps une fontaine du don de la santé. Des harpies s'emparèrent plus tard des pics voisins, capturant les wyvernes qui y nichaient et souillant les eaux de la fontaine. Thrall vint les affronter, avec Cairne Bloodhoof et ses taurens à ses côtés, et brisa une bande de centaures pour obtenir un Glyphe de purification et purifier ce que les harpies avaient corrompu. Les wyvernes libérées les emportèrent jusqu'au pic lui-même.\n\nCette vieille paix avec la terre a disparu dans le sud. La KapitalRisk a mis à nu la combe des Cisailles, abattant ses arbres, étouffant l'air de suie et souillant l'eau d'huile et de déchets, jusqu'à ce que les esprits de la montagne crient assez fort pour que des chamans les entendent jusqu'à Orgrimmar.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Désolace",
		short = "Theradras, fille de Therazane la Mère-pierre, sommeillait jadis sous une prairie fertile.",
		full = "Theradras, fille de Therazane la Mère-pierre, sommeillait jadis sous une prairie fertile. Des chamans taurens, persuadés que la Terre-mère elle-même demeurait en dessous, l'appelèrent pendant des décennies jusqu'à ce qu'enfin quelque chose réponde : non pas la Terre-mère, mais Theradras, tirée de son sommeil et furieuse. Elle se nourrit de la terre pour restaurer sa forme affaiblie, et les prairies moururent en un instant. Les taurens nommèrent ce qui restait Désolace.\n\nZaetar, fils du seigneur de la forêt Cénarius, vint pour l'entraver, mais il l'aima au contraire, et elle l'aima en retour. De leur union naquirent les centaures, dont le premier acte fut d'assassiner leur propre père. Ils se multiplièrent rapidement et chassèrent les taurens de la contrée, déclenchant des siècles de guerre entre les deux races.\n\nTheradras demeure encore à Maraudon, sous les canyons de l'ouest, et c'est là que les centaures font remonter la naissance de leur race.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Féralas",
		short = "Féralas surgit, étrange, au milieu de ses voisines, une forêt tropicale d'arbres antiques là où les déserts alentour ne promettent que la poussière.",
		full = "Féralas surgit, étrange, au milieu de ses voisines, une forêt tropicale d'arbres antiques là où les déserts alentour ne promettent que la poussière. Parmi la verdure se dressent çà et là les ruines des elfes, à demi englouties par les racines et les lianes, la plus grande d'entre elles étant la cité ensevelie de Hache-tripes.\n\nLes ogres Gordunni tiennent désormais Féralas, et ils se la sont appropriée en la brisant. Ils ont abattu des pans entiers de forêt, et leur souillure s'est posée sur la contrée comme une maladie. Au-delà des murs de Hache-tripes, leurs bandes de pillards incendient les villages et assassinent les voyageurs dans les bois du sud, une corruption qui se répand dans les terres sauvages et dont l'origine remonte aux ruines souterraines.\n\nDes taurens Totem sinistre vivent encore dispersés dans la région, traqués par ceux qui se souviennent de ce que la tribu a fait.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Marécage d'Âprefange",
		short = "Ici, les moustiques ne s'arrêtent jamais, et la boue non plus.",
		full = "Ici, les moustiques ne s'arrêtent jamais, et la boue non plus. Les arbres entremêlent leurs frondes si épaisses au-dessus de l'eau que la lumière du soleil n'y descend qu'en éclats, et crocilisques et murlocs guettent dans les eaux saumâtres où la mer rencontre le marais. Au sud, les dragons noirs se rassemblent en si grand nombre que les gens appellent simplement l'endroit la tourbière du Ver.\n\nJaina Proudmoore fit de cette contrée sauvage un premier véritable foyer, menant son peuple ici après la bataille du mont Hyjal pour fonder Theramore sur son île rocheuse. Les murailles de sa cité étincellent, mais elles l'enferment aussi : au-delà des postes de contrôle épars sur la route des Tarides, le marais reste aussi sauvage que jamais, et sa garnison s'est amenuisée au fil de désertions silencieuses que nul ne sait expliquer.\n\nC'est ici aussi que la paix entre la Horde et l'Alliance se brisa pour de bon. L'amiral Daelin Portvaillant mena la flotte de Kul Tiras contre la Horde dans le marais, et l'escarmouche qui suivit s'acheva par sa mort, changeant la trêve en inimitié déclarée.\n\nMur-de-Fougères se dresse là où les ogres Cognepierres ouvrirent leurs portes à la Horde. Au-delà, la route des Tarides est déserte et tombe en décrépitude, surveillée seulement par les raptors et les araignées qui ont toujours régné sur ces terres.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "Le sable emplit le lieu où se dressait autrefois une jungle. Avant que le monde ne soit brisé, Tanaris était verdoyante, revendiquée comme territoire par l'empire Gurubashi.",
		full = "Le sable emplit le lieu où se dressait autrefois une jungle. Avant que le monde ne soit brisé, Tanaris était verdoyante, revendiquée comme territoire par l'empire Gurubashi. Lorsque la Grande fracture déchira la terre, la jungle mourut et ce qui en restait se durcit en dunes et en pierre. Une tribu de trolls se retrouva prisonnière ici lorsque les eaux se retirèrent, et au fil des longues années qui suivirent, leurs corps et leurs coutumes se plièrent au désert jusqu'à ce qu'ils ne soient plus les trolls qu'ils avaient été, mais des trolls des sables, les Sandfury, un peuple façonné par la terre qui l'avait piégé.\n\nLes gobelins du cartel Gentepression choisirent cette terre désolée pour leur commerce, fondant Gadgetzan et Port Gentepression, car le désert est ce qui, sur Kalimdor, ressemble le plus à leur patrie engloutie où ils puissent s'installer. Les docks de Gentepression s'avancent vers les îles au-delà, mais les gobelins gardent leurs navires pour eux, peu disposés à faire traverser les eaux à aucune autre race.\n\nSous les dunes et les montagnes du sud, les tunnels s'étendent sur des lieues, en grande partie inexplorés, et ceux qui y descendent ne reviennent pas toujours raconter ce qu'ils y ont trouvé.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "L'automne règne sur Azshara depuis dix mille ans, ses arbres flamboyant d'orange et de rouge au-dessus de falaises qui plongent dans le corail où repose encore une cité.",
		full = "L'automne règne sur Azshara depuis dix mille ans, ses arbres flamboyant d'orange et de rouge au-dessus de falaises qui plongent dans le corail où repose encore une cité. Azshara fut jadis la plus grande métropole que les elfes de la nuit aient jamais élevée, et lorsque vint la guerre des Anciens, elle sombra presque tout entière dans la mer. Quelques bâtiments brisés s'accrochent encore à la falaise, contemplant leurs propres ruines sous les eaux.\n\nBien plus tard, lorsqu'Illidan Hurlorage s'enfuit vers le nord depuis le mont Hyjal avec ses nagas, suivi de mur'guls et de satyres, il ravagea la côte d'Azshara, détruisant les ports des elfes de la nuit pour que nul ne puisse le suivre jusqu'au tombeau de Sargeras. Maiev Shadowsong et ses Guetteuses vinrent derrière lui, abattant les créatures rendues folles qu'il laissait dans son sillage.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Gangrebois",
		short = "Les arbres de Gangrebois ne poussent pas tant qu'ils ne pourrissent. Leur écorce suinte une ichor maladive, leurs feuilles pendent, noires et recroquevillées, et la faune qui vit sous eux naît tordue et affamée par la corruption du sol.",
		full = "Les arbres de Gangrebois ne poussent pas tant qu'ils ne pourrissent. Leur écorce suinte une ichor maladive, leurs feuilles pendent, noires et recroquevillées, et la faune qui vit sous eux naît tordue et affamée par la corruption du sol.\n\nCette pourriture n'était pas un accident de la nature. Tandis que la Légion ardente avançait vers le mont Hyjal, Archimonde ordonna que la forêt soit brisée afin d'affaiblir les elfes de la nuit qui gardaient la montagne, et le seigneur de l'effroi Tichondrius exécuta cet ordre à l'aide d'une relique de démoniste d'une terrible puissance, le Crâne de Gul'dan. La terre y répondit en mourant de l'intérieur : les anciens devinrent pourris et violents, les bêtes subirent des mutations, la terre elle-même fut empoisonnée.\n\nC'est ici qu'Illidan Hurlorage fit le choix qui façonna le reste de sa vie. Apprenant que le crâne pouvait être retourné contre la corruption même qu'il avait causée, Illidan pénétra seul dans Gangrebois, abattit Tichondrius et s'empara de la relique. Il ne la rendit pas ensuite. Sa soif de magie se révéla plus forte que sa prudence, et pour avoir usé de la propre puissance de la Légion, il fut banni par son propre frère, Malfurion.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Cratère d'Un'Goro",
		short = "Le cratère d'Un'Goro s'étend, enclavé entre trois déserts, telle une plaie verdoyante creusée dans le sud de Kalimdor, là où le monde oublie d'être stérile.",
		full = "Le cratère d'Un'Goro s'étend, enclavé entre trois déserts, telle une plaie verdoyante creusée dans le sud de Kalimdor, là où le monde oublie d'être stérile. Des dinosaures plus anciens que la mémoire parcourent sa jungle, certains ayant atteint des tailles qu'aucun être vivant ne devrait atteindre, et des élémentaires de terre et de feu marchent paisiblement parmi eux. Sur les crêtes qui le dominent se dressent des pylônes que nul n'a jamais su expliquer.\n\nPendant la guerre des Sables changeants, les elfes de la nuit furent repoussés à travers ce cratère jusqu'aux confins du désert de Tanaris, et c'est là que l'avancée des Qiraji se brisa. Quelque chose dans Un'Goro même refusa de laisser les envahisseurs s'emparer de la terre, bien que nul n'ait jamais dit quoi.\n\nUne expédition menée par Williden et Hol'anyee Marshal tenta un jour de prendre pied ici, mais la sauvagerie du cratère dépassa tout ce à quoi ils s'étaient préparés. Leurs camps furent submergés, et les survivants s'enfuirent vers les hauteurs, livrant leur dernier combat à l'endroit qu'on appelle aujourd'hui le Refuge des Marshal.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Reflet-de-Lune",
		short = "Reflet-de-Lune repose dans un cercle de montagnes, vallée cachée où la forêt n'a jamais connu la corruption.",
		full = "Reflet-de-Lune repose dans un cercle de montagnes, vallée cachée où la forêt n'a jamais connu la corruption. En son cœur s'étend le lac Elune'ara, nommé d'après la déesse elle-même, et dans la ville de Havrenuit, sur sa rive, taurens et elfes de la nuit se côtoient sans querelle, unis par une même vénération de la nature que les gardiens de Reflet-de-Lune ne laisseront pas se briser.\n\nC'est dans cette vallée que vint Malfurion Hurlorage au temps de la guerre des Anciens, alors que les elfes de la nuit étaient au bord de la ruine face à la Légion. Malfurion savait que son peuple ne pourrait vaincre seul, et il mena Tyrande Whisperwind et son frère Illidan dans la quiétude sacrée de Reflet-de-Lune pour implorer l'aide de Cénarius. Le demi-dieu répondit, et après que la Grande fracture eut remodelé le monde, les gardiens du bosquet et les dryades qui s'étaient abrités ici s'en allèrent parcourir le monde. Cénarius lui-même ne partit jamais, et Reflet-de-Lune devint la terre la plus sacrée du culte druidique.\n\nSous ses innombrables tertres dorment les sanctuaires des druides d'antan, et sous les eaux d'Elune'ara dort le demi-dieu Omen, jadis bien-aimé d'Élune, d'un sommeil agité.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "Le désert s'étend à l'extrémité sud-ouest de Kalimdor, étendue de roches brisées et de sable que l'on atteint par la large piste venant d'Un'Goro.",
		full = "Le désert s'étend à l'extrémité sud-ouest de Kalimdor, étendue de roches brisées et de sable que l'on atteint par la large piste venant d'Un'Goro. Sous sa surface gisent les vestiges de l'empire aqir, Ahn'Qiraj, dont les elfes de la nuit scellèrent le temple central pour empêcher quelque chose de terrible de s'éveiller. Les ruines éparpillées à travers Silithus, et les ruches silithides qui criblent désormais le sable, prouvent assez que le sceau n'a pas tenu.\n\nIl y a longtemps, les Qiraji eux-mêmes furent repoussés derrière le mur du Scarabée et emprisonnés là au lendemain de la guerre des Sables changeants. Leurs serviteurs, les silithides, restèrent libres, et au fil des siècles ils se multiplièrent et se répandirent dans tout le sud de Kalimdor, jusqu'à ce que les elfes de la nuit jugent la menace trop grande pour se contenter de la surveiller, et se tournent plutôt vers la réouverture des portes d'Ahn'Qiraj pour achever ce que le mur n'avait fait que retarder.\n\nLe Cercle cénarien monte la garde depuis le Fort cénarien, suivant les essaims silithides et se demandant s'ils ne sont pas un danger trop grand pour qu'un seul peuple l'affronte seul.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Berceau-de-l'Hiver",
		short = "La neige s'étend, intacte, sur Berceau-de-l'Hiver, dont la beauté demeure inaltérée même là où les démons ont envahi les confins du sud. Il abritait jadis nombre de membres du vol draconique bleu, parmi lesquels Haleh, la compagne de Malygos.",
		full = "La neige s'étend, intacte, sur Berceau-de-l'Hiver, dont la beauté demeure inaltérée même là où les démons ont envahi les confins du sud. Il abritait jadis nombre de membres du vol draconique bleu, parmi lesquels Haleh, la compagne de Malygos.\n\nIl y a dix mille ans, les Bien-nés élevèrent ici la cité de Kel'Theril, après avoir volé le cristal de Zin-Malor dans un temple d'Eldarath. Ils ne purent résister à l'envie d'éprouver sa puissance, et lorsqu'il se brisa, la malédiction qu'il libéra les dévora. La Grande fracture acheva ce que le cristal avait commencé, et Kel'Theril tomba en ruine. Ses morts ne sont jamais partis. Plus tard, des hauts-elfes vinrent de Quel'Thalas à la recherche des éclats du cristal, et la même folie s'empara d'eux. Désormais, leurs fantômes errent dans les ruines aux côtés de ceux qu'ils étaient venus étudier.\n\nLes gobelins tiennent Long-guet au cœur de la vallée, et les elfes de la nuit montent toujours ici leur propre garde, protégeant une patrie plus ancienne que les deux peuples.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Cité de Stormwind",
		short = "Stormwind se releva en pierre blanche après que la Horde orque l'eut incendiée, rebâtie par la guilde des Maçons sous le règne du jeune roi Varian.",
		full = "Stormwind se releva en pierre blanche après que la Horde orque l'eut incendiée, rebâtie par la guilde des Maçons sous le règne du jeune roi Varian. Mais lorsque les coffres de la couronne se vidèrent à cause des dettes de guerre et que la noblesse refusa à la guilde ses salaires, la protestation du maître de guilde Edwin VanCleef reçut pour réponse la dissolution de la guilde. Des émeutes s'ensuivirent, et dans le chaos, la reine Tiffin Wrynn fut tuée. La colère de Varian chassa les maçons en exil dans la Marche de l'Ouest, où ils devinrent la Confrérie défias, tandis que dans l'ombre du trône, une conseillère nommée Katrana Prestor dressait discrètement le roi contre la guilde à ses propres fins.\n\nLe roi Varian a depuis disparu dans des circonstances suspectes, et sur l'insistance de dame Prestor, la couronne fut confiée à son jeune fils, le prince Anduin, afin de préserver l'ordre dans le royaume. Le généralissime Bolvar Fordragon sert de régent de Stormwind et de commandant de ses forces, tandis que dame Prestor le conseille sur l'emploi des ressources du royaume, insoupçonnée et incontestée au sein du donjon.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar s'éleva dans les années qui suivirent le mont Hyjal, lorsque le chef de guerre Thrall mena son peuple jusqu'à une côte désolée de Kalimdor.",
		full = "Orgrimmar s'éleva dans les années qui suivirent le mont Hyjal, lorsque le chef de guerre Thrall mena son peuple jusqu'à une côte désolée de Kalimdor. Il nomma la contrée Durotar en l'honneur de son père, et la cité qu'il y éleva, il la nomma Orgrimmar, en l'honneur d'Orgrim Marteau du Destin, l'ami et mentor qui l'avait façonné. Elle fut bâtie rapidement, mais non sans soin : murailles robustes, portes massives, hautes tours, et les montagnes dans son dos taillées pour faire partie de la forteresse elle-même, de sorte que la terre montait la garde sur la cité.\n\nLa Horde qui la bâtit n'était plus la Horde qui avait jadis embrasé le monde. La malédiction démoniaque brisée, le peuple de Thrall se détourna de la conquête pour se tourner vers la survie, et Orgrimmar fut élevée autant par d'autres que par les orcs : gobelins, taurens et trolls Darkspear travaillèrent à leurs côtés, et le Mok'Nathal Rexxar prêta main-forte à l'ouvrage. Centaures, harpies, lézards-tonnerre, kobolds et hurans mirent tous à l'épreuve la jeune cité durant ses premières années, mais elle tint bon et devint la demeure non seulement des orcs, mais aussi des trolls, des taurens et, avec le temps, des Réprouvés nouvellement accueillis au sein de la Horde.\n\nLe vent lui-même n'est pas un ami ici : les vents tranchants balaient les vallées avec assez de force pour arracher les toits des bâtiments construits sans soin.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "Ironforge est la capitale des nains, creusée dans les profondeurs de la montagne d'Ironforge, au nord de Dun Morogh, terre ancestrale des nains et l'une des plus anciennes cités d'Azeroth.",
		full = "Ironforge est la capitale des nains, creusée dans les profondeurs de la montagne d'Ironforge, au nord de Dun Morogh, terre ancestrale des nains et l'une des plus anciennes cités d'Azeroth. C'est la capitale de Khaz Modan, gouvernée par le roi Magni Bronzebeard, du clan Bronzebeard.\n\nVaste cité souterraine d'artisans, d'explorateurs, de mineurs et de guerriers, célèbre pour son industrie et comme centre commercial de l'Alliance, Ironforge est à la fois forteresse et capitale, un témoignage de la force et de la résilience des nains. La cité se compose d'anneaux concentriques et de niveaux plus petits enfouis plus profondément, qui rayonnent tous à partir de la Grande Forge qui lui a donné son nom, en son centre. Elle regorge de petits passages, de boutiques creusées dans les parois rocheuses et de salles caverneuses. L'atmosphère y est animée, bruyante et industrieuse, mais chaleureuse ; les feux ronflent dans les âtres des auberges et des boutiques, et l'on y entend force rires et réjouissances naines. Contrairement à Stormwind et à Darnassus, la cité est une immense caverne creusée dans la terre par les nains eux-mêmes ; le plafond comme le sol sont de pierre dure.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "Thunder Bluff se dresse sur quatre plateaux balayés par les vents au-dessus des prairies de Mulgore, accessible seulement par des ascenseurs de corde et de bois de facture taurène, ou par de longues passerelles tendues entre les hauteurs.",
		full = "Thunder Bluff se dresse sur quatre plateaux balayés par les vents au-dessus des prairies de Mulgore, accessible seulement par des ascenseurs de corde et de bois de facture taurène, ou par de longues passerelles tendues entre les hauteurs. Tentes, longues maisons et totems peints couronnent chaque sommet. Pendant des générations, les taurens errèrent en peuple nomade, harcelés sans relâche par les centaures qui parcouraient Kalimdor. C'est Cairne Bloodhoof, chef de la tribu Bloodhoof, qui mit fin à cet exil. Lorsque le chef de guerre Thrall et sa nouvelle Horde arrivèrent à Mulgore pendant la troisième guerre, leur force s'unit à celle de Cairne, et ensemble ils brisèrent les centaures et conquirent enfin les prairies pour les taurens. Sur les plateaux, Cairne éleva un refuge ouvert à toutes les tribus dispersées, et avec le temps ces tribus se plièrent à son autorité comme un seul peuple, en désaccord parfois sur la voie à suivre, mais jamais sur sa sagesse à les guider.\n\nLes falaises portent encore le poids de cette fondation dans leurs hauteurs et leurs passerelles, dans les tentes des tribus rassemblées sous le toit d'un seul chef.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Les elfes de la nuit bâtirent Darnassus après la troisième guerre, lorsque leur longue immortalité les eut abandonnés. Beaucoup ne purent supporter le poids soudain du vieillissement et de la fragilité.",
		full = "Les elfes de la nuit bâtirent Darnassus après la troisième guerre, lorsque leur longue immortalité les eut abandonnés. Beaucoup ne purent supporter le poids soudain du vieillissement et de la fragilité. Un certain nombre de druides endeuillés résolurent de planter un nouvel Arbre-Monde pour restaurer leur lien avec le monde éternel. Malfurion Hurlorage ayant disparu, Fandral Staghelm endossa le manteau d'archidruide et mena l'entreprise. L'arbre qu'ils firent croître, Teldrassil, s'éleva au large de la côte jusqu'à ce que sa couronne perce les nuages, et parmi ses branches, les elfes de la nuit fondèrent leur cité comme un témoignage de la survie de leur peuple.\n\nDarnassus s'ouvre sur le ciel, contrairement aux cités closes et fortifiées des humains et des nains. Elle est bâtie autour d'un vaste lac, dont les rives sont reliées par de gracieux ponts, et ses allées sont tapissées de feuilles mortes. Le temple de la Lune s'élève au-dessus des arbres, siège de la grande prêtresse Tyrande Whisperwind et de ses Sœurs d'Élune, à côté du palais de Justice à colonnades où les Sentinelles montent la garde. La cité demeure ce pour quoi elle fut bâtie : un refuge paisible, et un monument à un peuple qui apprend à vivre avec la mortalité.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "Bien avant que les Réprouvés ne se l'approprient, l'Undercity avait un nom et une fonction. Loin sous le palais de Lordaeron s'étendaient les antiques cryptes de ses morts royaux, ses cachots, ses égouts.",
		full = "Bien avant que les Réprouvés ne se l'approprient, l'Undercity avait un nom et une fonction. Loin sous le palais de Lordaeron s'étendaient les antiques cryptes de ses morts royaux, ses cachots, ses égouts. Elle n'était destinée qu'aux prisonniers et aux cadavres, mais les plus pauvres du peuple de Lordaeron s'entassaient malgré tout dans ces ténèbres, et les rafles des gardes pour les en chasser ne duraient jamais.\n\nLorsque l'emprise du roi-liche sur ses créatures se relâcha, Sylvanas Windrunner rompit avec le Fléau, emmenant les morts-vivants qui avaient conservé leur esprit, et se retourna contre Arthas, le prince déchu qui avait fait d'elle ce qu'elle était. Elle l'attira dans un piège au sein du royaume en ruine ; il s'échappa avec l'aide de Kel'Thuzad et s'enfuit vers le nord pour devenir lui-même le roi-liche. Sylvanas et ses fidèles, restés maîtres du terrain, se nommèrent les Réprouvés et revendiquèrent les cryptes sous la capitale dévastée, achevant la forteresse que le Fléau avait commencée.\n\nCe qui se dresse aujourd'hui est un labyrinthe conçu pour la défense : des rivières de fange toxique courent dans chaque avenue, et l'air est chargé de vapeurs que les vivants peinent à respirer. Pour les Réprouvés, c'est un abri dans un monde qui les pourchasse encore.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

